133: export async function launchWorkspace2<
134:   WorkspaceProps extends object,
135:   WindowProps extends object,
136:   GroupProp extends object,
137: >(
138:   workspaceName: string,
139:   workspaceProps: WorkspaceProps | null = null,
140:   windowProps: WindowProps | null = null,
141:   groupProps: GroupProp | null = null,
142: ): Promise<boolean> {
143:   const storeState = workspace2Store.getState();
144: 
145:   if (!storeState.registeredWorkspacesByName[workspaceName]) {
146:     throw new Error(`Unable to launch workspace ${workspaceName}. Workspace is not registered`);
147:   }
148:   const windowDef = getWindowByWorkspaceName(workspaceName);
149:   if (!windowDef) {
150:     throw new Error(`Unable to launch workspace ${workspaceName}. Workspace is not registered to a workspace window`);
151:   }
152: 
153:   const { openedGroup } = storeState;
154:   const { name: windowName } = windowDef;
155:   const groupDef = getGroupByWindowName(windowName);
156:   if (!groupDef) {
157:     throw new Error(
158:       `Unable to launch workspace ${workspaceName}. Workspace window ${windowDef.name} is not registered to a workspace group`,
159:     );
160:   }
161: 
162:   const openedWindowIndex = getOpenedWindowIndexByWorkspace(workspaceName);
163:   const isWindowAlreadyOpened = openedWindowIndex >= 0;
164: 
165:   // if current opened group is not the same as the requested group, or if the group props are different, then prompt for unsaved changes
166:   if (openedGroup && (openedGroup.groupName !== groupDef.name || !arePropsCompatible(openedGroup.props, groupProps))) {
167:     const okToCloseWorkspaces = await promptForClosingWorkspaces({ reason: 'CLOSE_WORKSPACE_GROUP', explicit: true });
168:     if (okToCloseWorkspaces) {
169:       workspace2Store.setState({
170:         ...storeState,
171:         openedGroup: {
172:           groupName: groupDef.name,
173:           props: groupProps,
174:         },
175:         openedWindows: [
176:           // discard all opened windows, open a new one with the requested workspace
177:           // most recently opened action appended to the end
178:           {
179:             windowName: windowName,
180:             openedWorkspaces: [newOpenedWorkspace(workspaceName, workspaceProps)], // root workspace at index 0
181:             props: windowProps,
182:             maximized: false,
183:           },
184:         ],
185:         isMostRecentlyOpenedWindowHidden: false,
186:       });
187:       return true;
188:     } else {
189:       return false;
190:     }
191:   } else if (isWindowAlreadyOpened) {
192:     const openedWindow = storeState.openedWindows[openedWindowIndex];
193:     const groupProps = storeState.openedGroup?.props ?? {};
194:     const isMostRecentlyOpenedWindowHidden = storeState.isMostRecentlyOpenedWindowHidden;
195:     const { openedWorkspaces } = openedWindow;
196: 
197:     if (arePropsCompatible(openedWindow.props, windowProps)) {
198:       // this case is tricky, this results in restoring the window if:
199:       // 1. the workspace is opened (but not necessarily as a leaf workspace)
200:       // 2. the props of the opened workspace is same as workspace props (from the function input)
201:       //
202:       // Otherwise, we close all workspaces in this window, and open this newly requested one
203:       const openedWorkspace = openedWorkspaces.find((w) => w.workspaceName === workspaceName);
204:       if (openedWorkspace && arePropsCompatible(openedWorkspace.props, workspaceProps)) {
205:         // restore the window if it is hidden or not the most recently opened one
206:         if (isMostRecentlyOpenedWindowHidden || openedWindowIndex !== storeState.openedWindows.length - 1) {
207:           workspace2Store.setState(workspace2StoreActions.restoreWindow(storeState, windowName));
208:         }
209:         return true;
210:       } else {
211:         const okToCloseWorkspaces = await promptForClosingWorkspaces({
212:           reason: 'CLOSE_WORKSPACE',
213:           explicit: false,
214:           windowName,
215:           workspaceName,
216:         });
217:         if (okToCloseWorkspaces) {
218:           workspace2Store.setState({
219:             ...storeState,
220:             openedGroup: {
221:               groupName: groupDef.name,
222:               props: storeState?.openedGroup?.props ?? groupProps,
223:             },
224:             openedWindows: [
225:               ...storeState.openedWindows.filter((_, i) => i !== openedWindowIndex),
226:               // most recently opened workspace at the end of the array
227:               {
228:                 windowName: windowName,
229:                 openedWorkspaces: [newOpenedWorkspace(workspaceName, workspaceProps)],
230:                 props: openedWindow?.props ?? windowProps,
231:                 maximized: false,
232:               },
